import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const C=JSON.parse('{"title":"CC Switch 接入 OpenCode：开源编程助手也能用中转站","description":"","frontmatter":{"title":"CC Switch 接入 OpenCode：开源编程助手也能用中转站","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","OpenCode","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/05-opencode.md","filePath":"guide/05-opencode.md"}'),n={name:"guide/05-opencode.md"};function l(d,e,c,r,s,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>OpenCode 是一个开源、免费的终端 AI 编程助手，支持接各种大模型。这篇教小白：用 CC Switch 把 AI 中转站接进 OpenCode，不用翻墙、不用绑卡，一个 Key 开箱即用。</p><h2 id="一、opencode-是什么" tabindex="-1">一、OpenCode 是什么 <a class="header-anchor" href="#一、opencode-是什么" aria-label="Permalink to &quot;一、OpenCode 是什么&quot;">​</a></h2><p>OpenCode 是开源社区里的 Claude Code 替代品，完全免费，跑在终端里，支持 OpenAI、Anthropic 等一堆模型接口。它的配置文件是 <code>opencode.json</code>，一堆 JSON 新手看着就头大——<strong>CC Switch 帮你管它</strong>。</p><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><ol><li><strong>中转站 API Key</strong>：后台 → API Keys → 创建，复制 <code>sk-</code> Key</li><li><strong>Node.js</strong>：nodejs.org 装 LTS 版</li><li><strong>装 OpenCode</strong>：官方文档或 GitHub 提供一键安装脚本，按平台执行即可</li><li><strong>下载 CC Switch</strong>：官网 ccswitch.io 或 GitHub Releases</li></ol><h2 id="三、在-cc-switch-里添加-opencode-供应商" tabindex="-1">三、在 CC Switch 里添加 OpenCode 供应商 <a class="header-anchor" href="#三、在-cc-switch-里添加-opencode-供应商" aria-label="Permalink to &quot;三、在 CC Switch 里添加 OpenCode 供应商&quot;">​</a></h2><ol><li>打开 CC Switch</li><li>左侧切换器选 <strong>OpenCode</strong> 应用</li><li>点右上角 <strong>+</strong></li><li>预设选 <strong>OpenAI Compatible</strong>（中转站都是兼容 OpenAI 格式的，选这个最稳） <ul><li>或者选 <strong>自定义</strong> 手动填</li></ul></li><li>填关键信息： <ul><li><strong>名称</strong>：如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：<code>https://ai.aklibk.com/v1</code></li><li><strong>API Key</strong>：粘贴中转站 Key</li><li><strong>模型</strong>：填一个支持的，如 <code>gpt-4o</code></li></ul></li><li>点 <strong>添加</strong></li></ol><blockquote></blockquote><blockquote><p>内置预设里还有 DeepSeek、智谱 GLM、Kimi、MiniMax、硅基流动等一堆，如果你中转站/直连这些，直接选预设只填 Key 更快。</p></blockquote><h2 id="四、切换并运行-opencode" tabindex="-1">四、切换并运行 OpenCode <a class="header-anchor" href="#四、切换并运行-opencode" aria-label="Permalink to &quot;四、切换并运行 OpenCode&quot;">​</a></h2><ol><li>在 OpenCode 面板点一下刚添加的供应商（选中）</li><li>打开终端，输入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opencode</span></span></code></pre></div></li><li>问一句&quot;你好&quot;——能回复就成功了</li></ol><blockquote></blockquote><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>报 401</td><td>API 地址或 Key 填错，核对</td></tr><tr><td>报模型不存在</td><td>换中转站后台实际有的模型名</td></tr><tr><td>想换模型</td><td>CC Switch 编辑供应商改模型，再切换</td></tr></tbody></table><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>OpenCode 接中转站：<strong>下载 CC Switch → OpenCode 面板添加（选 OpenAI Compatible + 填地址 Key）→ 切换 → 终端跑 opencode</strong>。</p><p>开源免费 + 一个 Key 通吃全家桶？试试 Aklibk API 中转站（ai.aklibk.com），国内直连、免绑卡、人民币按量付费。</p><blockquote><p>下一篇预告：OpenClaw——能接管你电脑的 AI 私人助理，接入教程来了。</p></blockquote>',20)])])}const u=o(n,[["render",l]]);export{C as __pageData,u as default};
